(() => {
 'use strict';const D=window.NastranDamping,C=window.NastranDynamics,$=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=(v,n=4)=>v.toLocaleString('ja-JP',{maximumFractionDigits:n});
 const pdf=(b,p)=>`https://documentation-be.hexagon.com/bundle/MSC_Nastran_2020_${b}/raw/resource/enus/MSC_Nastran_2020_${b}.pdf#page=${p}`;
 for(const [attr,book]of [['dyn','Dynamic_Analysis_User_Guide'],['qrg','Quick_Reference_Guide']])document.querySelectorAll(`[data-${attr}]`).forEach(a=>{a.href=pdf(book,a.dataset[attr]);a.target='_blank';a.rel='noopener';});
 const label=(x,y,s,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}">${esc(s)}</text>`;
 const line=(points,color,dash='')=>`<path d="${points.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)},${y.toFixed(2)}`).join(' ')}" stroke="${color}" stroke-width="3" fill="none"${dash?` stroke-dasharray="${dash}"`:''}/>`;
 function axes(xTicks,yTicks,x,y,xLabel,yLabel,bottom=245){let out='';for(const [v,s]of xTicks)out+=`<path d="M${x(v)} 35V${bottom}" stroke="#e1e8f2"/>`+label(x(v),bottom+25,s);for(const [v,s]of yTicks)out+=`<path d="M75 ${y(v)}H625" stroke="#e1e8f2"/>`+label(64,y(v)+6,s,'end');return out+label(75,36,yLabel,'start')+label(625,bottom+48,xLabel,'end');}
 const metric=(title,value,unit)=>`<div><small>${title}</small><strong>${value}</strong><span>${unit}</span></div>`;
 function compare(){const z=Number($('damp-zeta').value),r=Number($('damp-r').value),a=D.coefficients(z),response=D.harmonic(r,z);
  $('damp-conversion').innerHTML=metric('TABDMP1 · CRIT',num(a.z),'減衰比 ζ = '+num(z*100)+'%')+metric('TABDMP1 · G',num(a.g),'g = 2ζ · 無次元')+metric('TABDMP1 · Q',num(a.Q),'Q = 1/(2ζ) · 無次元')+metric('この模型の粘性係数 c',num(a.c),'N·s/mm');
  $('damp-r-label').textContent=num(r,2)+'（f ≈ '+num(r*D.fn,3)+' Hz）';$('damp-response-values').classList.add('response');$('damp-response-values').innerHTML=metric('粘性の振幅倍率',num(response.viscous),'c = '+num(a.c)+' N·s/mm')+metric('構造の振幅倍率',num(response.structural),'g = '+num(a.g));
  const x=r=>75+(r-.2)/1.8*550,y=v=>245-(Math.log10(v)+.6)/2.6*210;
  let s=axes([[.2,'0.2'],[.5,'0.5'],[1,'1'],[1.5,'1.5'],[2,'2']],[[.5,'0.5'],[1,'1'],[5,'5'],[10,'10'],[50,'50']],x,y,'r = f / fₙ','振幅倍率');
  for(const [key,color,dash]of [['viscous','#315bd0',''],['structural','#bd6d3e','7 5']]){s+=line(Array.from({length:721},(_,i)=>{const q=.2+i/400;return [x(q),y(D.harmonic(q,z)[key])];}),color,dash);s+=`<circle cx="${x(r)}" cy="${y(response[key])}" r="5" fill="${color}"/>`;}$('damp-response-chart').innerHTML=s;
 }
 function plotDecay(){const z=Number($('decay-zeta').value),x=t=>75+t/.2*550,y=u=>135-u*90;let s=axes([[0,'0'],[.05,'0.05'],[.1,'0.10'],[.15,'0.15'],[.2,'0.20']],[[-1,'−1'],[0,'0'],[1,'1']],x,y,'t (s)','u (mm)',230);s+=line(Array.from({length:601},(_,i)=>{const t=.2*i/600;return [x(t),y(D.decay(t,z))];}),'#315bd0');$('decay-chart').innerHTML=s;}
 function plotRayleigh(){const x=f=>75+(f-25/(2*Math.PI))/(225/(2*Math.PI))*550,y=z=>245-z/.04*210;let s=axes([[5,'5'],[10,'10'],[20,'20'],[30,'30'],[39,'39']],[[0,'0'],[.01,'1'],[.02,'2'],[.03,'3'],[.04,'4']],x,y,'fₙ (Hz)','減衰比 (%)');s+=line([[75,y(.02)],[625,y(.02)]],'#8c9cb5','6 5');for(const [key,color]of [['mass','#478b7c'],['stiffness','#bd6d3e'],['total','#315bd0']])s+=line(Array.from({length:181},(_,i)=>{const w=25+i*225/180;return [x(w/(2*Math.PI)),y(D.rayleigh(w)[key])];}),color);for(const w of [50,200])s+=`<circle cx="${x(w/(2*Math.PI))}" cy="${y(.02)}" r="5" fill="#315bd0"/>`;$('rayleigh-chart').innerHTML=s;}
 $('damp-zeta').addEventListener('change',compare);$('damp-r').addEventListener('input',compare);$('decay-zeta').addEventListener('change',plotDecay);
 const schemaCD=D.cdamp.map(f=>f[0]);
 function fieldTarget(r,i){if(r.name==='CDAMP2')return '#damp-field-CDAMP2-'+i;if(r.name==='PARAM')return '#damp-field-'+r.values[1]+'-'+i;return 'dynamics.html#field-'+r.name+'-'+r.line+'-'+i;}
 function showExample(id){const v=D.variants[id];if(!v)return;$('damp-example').value=id;$('damp-filename').textContent=v.filename;$('damp-example-note').textContent=v.note;$('damp-case-code').textContent=[...v.exec,...v.control,'BEGIN BULK'].join('\n');$('damp-raw').textContent=v.deck;
  $('damp-input-tables').innerHTML=v.focusRows.map(r=>{const labels=r.name==='CDAMP2'?schemaCD:C.cards[r.name].lines[r.line].map(f=>f.label);return `<div class="nf-card"><div class="nf-caption"><strong>${r.name}${r.name==='PARAM'?' · '+r.values[1]:''}</strong><span>${r.line?'継続行':''}</span></div><div class="nf-scroll" tabindex="0" aria-label="${r.name}の8文字フィールド表。横スクロールできます"><table class="nf-table"><thead><tr>${labels.map((l,i)=>`<th scope="col"><small>第${i+1}欄</small><span>${i*8+1}–${i*8+8}列</span><b><a href="${fieldTarget(r,i)}">${esc(l)}</a></b></th>`).join('')}</tr></thead><tbody><tr>${labels.map((l,i)=>{const v=r.text.slice(i*8,i*8+8);return `<td${v.trim()?'':' class="nf-empty"'}>${v.trim()?'<code>'+esc(v)+'</code>':'<span aria-label="8文字分の空欄">空欄</span>'}</td>`;}).join('')}</tr></tbody></table></div></div>`;}).join('');
 }
 function showField(key){if(key!=='CDAMP2'&&!D.params[key])return;$('damp-field-picker').value=key;const p=D.params[key];const fields=key==='CDAMP2'?D.cdamp:[['カード名','PARAMと書きます。BEGIN BULKより後の設定カードです。Case ControlのSDAMPINGなどとは別の書き方です。'],['N','設定するパラメータの名前。この説明では'+key+'を使います。同じPARAMでも名前が違えば、値の意味や単位も変わります。'],['V1',p.meaning+' この配布例の入力値は'+p.value+'です。'],['V2',key.startsWith('ALPHA')?'ALPHA1/2は内部で複素数として扱うパラメータです。V1が実部、V2が虚部。今回の実数のRayleigh係数にはV2へ0.を明示します。虚部は位相に関わる成分で、この例では使わないため0です。α₂をここへ書くのではなく、別のPARAM ALPHA2行へ書きます。':'この例の'+key+'は第1の値だけを使います。第2の値は空欄です。次の設定は別のPARAM行に書きます。'],...Array.from({length:5},()=>['未使用',D.blank]),['次行','このPARAMは1行で完結するため空欄にします。8文字幅を残して行を終えます。']];
  $('damp-field-detail').innerHTML=`<article class="field-detail" id="damp-card-${key}"><div class="eyebrow">${key==='CDAMP2'?'CDAMP2':'PARAM '+key}</div><h3>${key==='CDAMP2'?'2つの自由度の間の粘性ダンパー':'パラメータ '+key+' の入力'}</h3>${key==='CDAMP2'?'<p>位置を結ぶ線の方向ではなく、各GRIDのCD座標系の成分番号で動きを選びます。同じ節点・同じ成分どうしは結びません。PDAMPや材料カードを参照せず、係数Bを直接入力します。</p>':''}<a href="${pdf('Quick_Reference_Guide',p?.page||1532)}" target="_blank" rel="noopener">原典 QRG PDF ${p?.page||1532} ↗</a><dl class="field-list">${fields.map(([label,help],i)=>`<div class="field-row damp-field" id="damp-field-${key}-${i}"><dt>${label}<span>第${i+1}欄 · ${i*8+1}–${i*8+8}列</span></dt><dd>${esc(help)}</dd></div>`).join('')}</dl></article>`;
 }
 $('damp-example').innerHTML=Object.entries(D.variants).map(([id,v])=>`<option value="${id}">${v.title}</option>`).join('');$('damp-example').addEventListener('change',()=>{const id=$('damp-example').value;showExample(id);location.hash='damp-example-'+id;});
 $('damp-field-picker').innerHTML=['CDAMP2',...Object.keys(D.params)].map(k=>`<option value="${k}">${k==='CDAMP2'?k:'PARAM '+k}</option>`).join('');$('damp-field-picker').addEventListener('change',()=>location.hash='damp-card-'+$('damp-field-picker').value);
 function route(){const h=location.hash;let m;if(m=/^#damp-example-([a-z]+)$/.exec(h)){showExample(m[1]);$('damp-input').scrollIntoView({block:'start'});}else if(m=/^#damp-(?:card|field)-(CDAMP2|G|W3|W4|KDAMP|ALPHA1|ALPHA2)(?:-\d+)?$/.exec(h)){showField(m[1]);requestAnimationFrame(()=>document.getElementById(h.slice(1))?.scrollIntoView({block:'start'}));}}
 let timer;function toast(t){$('damp-toast').hidden=false;$('damp-toast').textContent=t;clearTimeout(timer);timer=setTimeout(()=>$('damp-toast').hidden=true,4000);}
 $('save-damping').addEventListener('click',()=>{const v=D.variants[$('damp-example').value],url=URL.createObjectURL(new Blob([v.deck],{type:'text/plain;charset=us-ascii'})),a=document.createElement('a');a.href=url;a.download=v.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('copy-damping').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(D.variants[$('damp-example').value].deck);toast('選んだ完成BDFをコピーしました');}catch{toast('コピーできませんでした。BDF保存を利用してください');}});
 compare();plotDecay();plotRayleigh();showExample('modal');showField('CDAMP2');window.addEventListener('hashchange',route);route();
})();
